'use strict';
const CACHE='baseera-offline-v04-finalquiz1';
const FILES=['/','/index.html','/style.css','/app.js','/pwa.js','/manifest.webmanifest','/icons/icon-180.png','/icons/icon-192.png','/icons/icon-512.png','/assets/salah.png','/assets/sawm.png','/assets/hajj.png'];
const TYPES={'.js':'javascript','.css':'text/css','.png':'image/png','.webmanifest':'json'};
async function verified(path){const response=await fetch(new Request(path,{credentials:'include',cache:'reload'}));if(!response.ok||response.redirected||new URL(response.url).origin!==self.location.origin)throw Error('Offline download requires access to Baseera.');const type=response.headers.get('content-type')||'';if(path==='/'||path==='/index.html'){if(!type.includes('text/html')||!(await response.clone().text()).includes('name="baseera-app"'))throw Error('Not an app document.');}else{const ext=path.slice(path.lastIndexOf('.'));if(!type.includes(TYPES[ext]))throw Error('Unexpected asset type.');}return response;}
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);try{await Promise.all(FILES.map(async path=>cache.put(path,await verified(path))));}catch(e){await caches.delete(CACHE);throw e;}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('baseera-offline-')&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();if(event.data?.type==='OFFLINE_STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE);const ok=(await Promise.all(FILES.map(p=>cache.match(p)))).every(Boolean);event.ports[0]?.postMessage({ready:ok,version:CACHE});})());});
self.addEventListener('fetch',event=>{const req=event.request,u=new URL(req.url);if(req.method!=='GET'||u.origin!==self.location.origin||u.search||!FILES.includes(u.pathname))return;event.respondWith((async()=>{if(req.mode==='navigate'){try{const live=await fetch(req);if(!live.ok||live.redirected)return live;const type=live.headers.get('content-type')||'';if(!type.includes('text/html')||!(await live.clone().text()).includes('name="baseera-app"'))return live;return (await caches.match('/'))||live;}catch(e){const cached=await caches.match('/');return cached||new Response('Connect to the internet to open Baseera for the first time.',{status:503,headers:{'Content-Type':'text/plain'}});}}const cached=await caches.match(u.pathname);return cached||fetch(req);})());});
